 "content": "from collections import deque

def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    py, px = p
                    if 0 <= py < h and 0 <= px < w and p not in seen and grid[py][px] == col:
                        seen.add(p)
                        q.append(p)
            out.append((col, cells))
    return out

def shape(cells):
    mr = min(r for r,c in cells)
    mc = min(c for r,c in cells)
    return frozenset((r-mr,c-mc) for r,c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    templates = {}
    for color, cells in comps:
        if color != 1:
            templates.setdefault(shape(cells), color)
    for color, cells in comps:
        if color == 1 and shape(cells) in templates:
            for r,c in cells:
                out[r][c] = templates[shape(cells)]
    return out

if __name__ == '__main__':
